# Read-only launch-surface inventory. Opaque wrappers are reported, never
# treated as proof that no indirect Tong entry exists. No raw arguments output.
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$entryMatches=[Collections.Generic.List[object]]::new();$errors=[Collections.Generic.List[string]]::new();$opaque=0;$tasks=0;$services=0;$runValues=0;$startupFiles=0;$wmiConsumers=0
function Digest([string]$Text){return [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($Text))).ToLowerInvariant()}
function Related([string]$Text){return $Text -match '(?i)Tong|D:\\node\\node\.exe|retold-pointer-irregular'}
try{
 $scheduler=New-Object -ComObject Schedule.Service;$scheduler.Connect();$folders=[Collections.Generic.Stack[object]]::new();$folders.Push($scheduler.GetFolder('\'))
 while($folders.Count){$folder=$folders.Pop();foreach($task in $folder.GetTasks(1)){$tasks++;$xml=$task.Xml;if(Related $xml){$entryMatches.Add(@{kind='task';path=$task.Path;enabled=$task.Enabled;instances=@($task.GetInstances(0)).Count;xmlSha256=(Digest $xml)})};foreach($action in $task.Definition.Actions){if($action.Type -ne 0 -or $action.Path -match '(?i)(cmd|powershell|pwsh|wscript|cscript|python|node)(\.exe)?$' -or $action.Arguments -match '(?i)\.ps1|\.cmd|\.bat|\.vbs|\.js'){$opaque++}}};foreach($child in $folder.GetFolders(0)){$folders.Push($child)}}
}catch{$errors.Add('TASK_ENUMERATION_UNAVAILABLE')}
try{foreach($service in (Get-CimInstance Win32_Service)){$services++;if(-not $service.PathName){$errors.Add('SERVICE_IMAGE_UNAVAILABLE');continue};if(Related ($service.Name+' '+$service.PathName)){$entryMatches.Add(@{kind='service';name=$service.Name;state=$service.State;startMode=$service.StartMode;pid=$service.ProcessId;imageSha256=(Digest $service.PathName)})};if($service.PathName -match '(?i)\.ps1|\.cmd|\.bat|cmd\.exe|pwsh\.exe|powershell\.exe'){$opaque++}}}catch{$errors.Add('SERVICE_ENUMERATION_UNAVAILABLE')}
foreach($hive in @('HKCU:','HKLM:')){foreach($branch in @('Software\Microsoft\Windows\CurrentVersion\Run','Software\Microsoft\Windows\CurrentVersion\RunOnce','Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run','Software\WOW6432Node\Microsoft\Windows\CurrentVersion\RunOnce')){try{$path=$hive+'\'+$branch;if(Test-Path -LiteralPath $path){$key=Get-Item -LiteralPath $path;foreach($name in $key.GetValueNames()){$runValues++;$value=[string]$key.GetValue($name);if(Related $value){$entryMatches.Add(@{kind='run-key';hive=$hive;branch=$branch;valueName=$name;sha256=(Digest $value)})};if($value -match '(?i)\.ps1|\.cmd|\.bat|\.vbs|\.js|powershell|pwsh|cmd\.exe'){$opaque++}}}}catch{$errors.Add('RUN_KEY_UNAVAILABLE')}}}
foreach($path in @([Environment]::GetFolderPath('Startup'),[Environment]::GetFolderPath('CommonStartup'))){try{foreach($file in (Get-ChildItem -LiteralPath $path -File -Force)){$startupFiles++;$hash=(Get-FileHash -LiteralPath $file.FullName).Hash.ToLowerInvariant();$text=$file.Name;if($file.Extension -ieq '.lnk'){$link=(New-Object -ComObject WScript.Shell).CreateShortcut($file.FullName);$text+=' '+$link.TargetPath+' '+$link.Arguments}else{$opaque++};if(Related $text){$entryMatches.Add(@{kind='startup-file';name=$file.Name;sha256=$hash})}}}catch{$errors.Add('STARTUP_FOLDER_UNAVAILABLE')}}
foreach($class in @('CommandLineEventConsumer','ActiveScriptEventConsumer')){try{foreach($consumer in (Get-CimInstance -Namespace root/subscription -ClassName $class)){$wmiConsumers++;$text=if($class -eq 'CommandLineEventConsumer'){$consumer.CommandLineTemplate}else{$consumer.ScriptText};if(Related $text){$entryMatches.Add(@{kind='wmi-consumer';class=$class;name=$consumer.Name;sha256=(Digest $text)})};$opaque++}}catch{$errors.Add('WMI_CONSUMER_ENUMERATION_UNAVAILABLE')}}
[ordered]@{at=[DateTime]::UtcNow.ToString('o');readOnly=$true;taskCount=$tasks;serviceCount=$services;runValueCount=$runValues;startupFileCount=$startupFiles;wmiConsumerCount=$wmiConsumers;opaqueWrapperCount=$opaque;enumerationErrors=@($errors.ToArray()|Select-Object -Unique);related=$entryMatches.ToArray();allEntrypointsProvenClosed=$false;productionReady=$false;reason='Inventory and current absence cannot exclude indirect launch wrappers or a future caller; original v1 has no inherited gate handoff.'}|ConvertTo-Json -Depth 6 -Compress
